message.content:
{
"css": ".itinerary { display: flex; flex-direction: column; gap: 40px; color: var(--ink); }
.day-group h2 { font-size: 16px; line-height: 22px; font-weight: 700; margin-bottom: 16px; }
.day-group h2 span { font-weight: 500; color: var(--muted); }
.place-row { display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: 9px; align-items: center; margin-bottom: 18px; }
.place-card { display: flex; align-items: stretch; border: 1px solid var(--border); border-radius: 6px; min-height: 96px; overflow: hidden; background: #fff; width: 100%; }
.place-photo { width: 96px; height: 96px; flex: 0 0 96px; object-fit: cover; }
.place-copy { flex: 1; min-width: 0; padding: 8px 12px; display: flex; flex-direction: column; gap: 4px; overflow-wrap: anywhere; }
.place-title { font-size: 14px; line-height: 19px; font-weight: 700; color: var(--ink); margin: 0; }
.place-type, .place-region { font-size: 14px; line-height: 19px; font-weight: 500; color: var(--muted); margin: 0; }
.place-grip { width: 18px; height: 18px; flex: 0 0 18px; margin-right: 6px; align-self: center; opacity: 0.4; }
input[type="checkbox"] { width: 22px; height: 22px; margin: 0; flex: 0 0 auto; align-self: center; }
partial-slot { display: block; margin-left: 31px; height: 18px; overflow: hidden; position: relative; }
.partial-card { min-height: 96px; border: 1px solid var(--border); border-radius: 6px; background: #fff; position: absolute; top: -78px; left: 0; width: 100%; display: flex; align-items: center; overflow: hidden; }
.partial-card img { width: 96px; height: auto; object-fit: cover; flex-shrink: 0; }
@media (max-width: 360px) {
.place-photo { width: 72px; height: 72px; flex: 0 0 72px; }
.place-copy { padding: 8px; }
}"
}
